PAYLOAD=''
import base64, zipfile, io, os, json, hashlib, sys, time
from pathlib import Path
import torch
zipfile.ZipFile(io.BytesIO(base64.b64decode(PAYLOAD))).extractall('/kaggle/working')
os.chdir('/kaggle/working'); sys.path.insert(0,os.getcwd())
from faceforge.data import manifest
from faceforge.train import train
print('CUDA:',torch.cuda.is_available(), torch.cuda.get_device_name(0) if torch.cuda.is_available() else 'none',flush=True)
if not torch.cuda.is_available(): raise RuntimeError('GPU unavailable')
files=sorted(Path('/kaggle/input').rglob('*.jpg'))[:2048]
if len(files)<2048: raise RuntimeError(f'Expected 2048 images, found {len(files)}')
os.makedirs('selected',exist_ok=True)
for i,p in enumerate(files): os.symlink(str(p),f'selected/{i:06}.jpg')
result=manifest('selected','manifest.json'); print('valid:',len(result['rows']),'rejected:',len(result['rejected']),flush=True)
train('manifest.json','run',epochs=5,batch=64,z_dim=128,width=32,device='cuda')
print('FINISHED',flush=True)
